var PATCH_LEVEL_SET = new Set(SINGLE_BLOCK_ADJACENCY_LEVEL_IDS);
var COLOR_ONLY_SOLVED_SET = new Set(SINGLE_BLOCK_COLOR_ONLY_SOLVED_LEVEL_IDS);
var applyColors = (level, patches) => {
  const byId = new Map(patches.map((patch) => [patch.blockId, patch]));
  return { ...level, blocks: level.blocks.map((block2) => {
    const patch = byId.get(block2.id);
    if (!patch) return block2;
    const current = block2.layers?.[0] ?? block2.color;
    if (current !== patch.from) throw new Error(`Lv${level.id}/${block2.id}: expected ${patch.from}, got ${current}`);
    return { ...block2, color: patch.color, ...block2.layers?.length ? { layers: [patch.color, ...block2.layers.slice(1)] } : {} };
  }) };
};
var applySingleBlockAdjacencyRepair = (level) => {
  const patches = SINGLE_BLOCK_COLOR_PATCHES[level.id];
  if (!patches) return level;
  const recolored = applyColors(level, patches);
  return COLOR_ONLY_SOLVED_SET.has(level.id) ? recolored : forceSolvabilityRepair(recolored);
};

